using System;using System.IO;using System.Reflection;using System.Collections;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class BossFreezeCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated save required");g.TryStartRun(42);g.SetPaused(true);g.SetReducedMotion(false);var f=BindingFlags.Instance|BindingFlags.NonPublic;var list=(IList)typeof(RunSimulator).GetField("enemies",f).GetValue(g.Run);list.Clear();var e=new EnemyState();typeof(EnemyState).GetProperty("Kind").SetValue(e,EnemyKind.Boss);typeof(EnemyState).GetProperty("Id").SetValue(e,999);list.Add(e);var w=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",f).GetValue(g);w.Reset(g.Run);g.PresentBattle();var views=(IDictionary)typeof(InkBattleWorld).GetField("enemies",f).GetValue(w);var v=views[999];var t=v.GetType();var body=(SpriteRenderer)t.GetField("body").GetValue(v);var ring=(SpriteRenderer)t.GetField("threat").GetValue(v);var old=body.transform.localPosition;t.GetField("previous").SetValue(v,new Vector2(100,100));t.GetField("current").SetValue(v,new Vector2(100,100));typeof(InkBattleWorld).GetField("freeze",f).SetValue(w,1f);g.PresentBattle();if(body.transform.localPosition!=old||Vector3.Distance(body.transform.localPosition,ring.transform.localPosition)>.001f)throw new Exception("Frozen ring drift");typeof(InkBattleWorld).GetField("freeze",f).SetValue(w,0f);g.PresentBattle();if(body.transform.localPosition==old||Vector3.Distance(body.transform.localPosition,ring.transform.localPosition)>.001f)throw new Exception("Resumed ring drift");var report=new{passed=true,scope="Injected boss position change while frozen, then resumed; ring matches body in both states"};File.WriteAllText(Path.GetFullPath("../docs/evidence/boss-freeze.json"),Newtonsoft.Json.JsonConvert.SerializeObject(report));return report;}}
